arguments.command:
cd /mnt/e/lindana && cat > /tmp/mini.lind <<'EOF'
Error {
  {
    (Error, Demo, ("late", 30)),
    (SpecialistGo,)
  }
  (Error, Demo, (s, n)), rd(SpecialistGo,) : [say "specialist: %s %i" s n; exit 0]
}
EOF
timeout 10 stack exec lindana -- /tmp/mini.lind 2>&1; echo "--- exit: $? ---"

cd /mnt/e/lindana && cat > /tmp/bags-tagged13.lind <<'EOF'
-- v13: gated specialist only. Producer lobs the tagged error at t0;
-- the gate lands ~25ms later via bytesBind completion.
{
  (Job, 3)
}

(Job, n) : [lob Workers (Go,); die]

Workers {
  (Go,) : [lob Error (Error, Demo, ("late", 30)); sleep 25; bytesBind GoGate [1]; die]
}

(Bytes, GoGate) : [lob Error (SpecialistGo,); die]

Error {
  (Error, Demo, (s, n)), rd(SpecialistGo,) : [say "specialist: %s %i" s n; exit 0]
}
EOF
timeout 5 stack exec lindana -- /tmp/bags-tagged13.lind 2>&1; echo "--- exit: $? ---"

cd /mnt/e/lindana && cat > /tmp/bags-tagged17.lind <<'EOF'
-- v17: gated specialist vs a hot pushback ping-pong.
{
  (Job, 3)
}

(Job, n) : [lob Workers (Go,); die]

Workers {
  (Go,) : [lob Error (Error, Demo, ("late", 30)); sleep 25; bytesBind GoGate [1]; die]
}

(Bytes, GoGate) : [lob Error (SpecialistGo,); die]

Error {
  (Error, Demo, (s, n)), rd(SpecialistGo,) : [say "specialist: %s %i" s n; exit 0]
  (Error, Demo, r) : [(HeadCheck, r)]
  (HeadCheck, r!) : [lob Error (Error, Demo, r)]
}
EOF
timeout 5 stack exec lindana -- /tmp/bags-tagged17.lind 2>&1 | head -5; echo "--- exit: $? ---"

